<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/discovery.php';$pageTitle='Gesuche entdecken';
$label=static fn(string $text):string=>function_exists('t')?t($text):$text;
try{$country=geo_country(isset($_GET['country_code'])?discovery_text($_GET,'country_code',2):null);$scope=discovery_text($_GET,'scope',16,'country');if(!in_array($scope,['country','international'],true))throw new InvalidArgumentException();}catch(InvalidArgumentException){abort_request(400,'Ungültiger Suchbereich.');}
$categoryIds=array_map(static fn(array $row):int=>(int)$row['id'],catalog_categories($pdo,true));$where=["w.status='active'","u.is_active=1","mc.is_active=1"];$parameters=[];
if($scope!=='international'){$where[]='w.country_code=?';$parameters[]=$country;}
if($categoryIds){$where[]='(w.category_id IS NULL OR w.category_id IN ('.implode(',',array_fill(0,count($categoryIds),'?')).'))';$parameters=array_merge($parameters,$categoryIds);}else $where[]='w.category_id IS NULL';
$idRaw=$_GET['id']??null;$selected=null;$page=filter_var($_GET['page']??'1',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>10000]])?:1;
if($idRaw!==null){if(!is_string($idRaw)||!ctype_digit($idRaw)||(int)$idRaw<1)abort_request(404,'Gesuch nicht gefunden.');$where[]='w.id=?';$parameters[]=(int)$idRaw;}
$q=$pdo->prepare('SELECT w.id,w.title,w.description,w.category_id,w.manufacturer,w.model,w.min_cents,w.max_cents,w.condition_label,w.country_code,w.scope,w.zip,w.radius_km,w.created_at,c.name AS category_name FROM market_wanted w JOIN users u ON u.id=w.user_id JOIN market_countries mc ON mc.code=w.country_code LEFT JOIN market_categories c ON c.id=w.category_id WHERE '.implode(' AND ',$where).' ORDER BY w.id DESC LIMIT 25 OFFSET '.(($page-1)*24));$q->execute($parameters);$wanted=$q->fetchAll();$hasNext=count($wanted)>24;$wanted=array_slice($wanted,0,24);if($idRaw!==null&&!$wanted)abort_request(404,'Gesuch nicht gefunden.');$countries=geo_countries();
include __DIR__.'/../includes/header.php';?>
<main class="container"><div class="page-heading"><p class="eyebrow"><?=h($label('Was andere gerade suchen'))?></p><h1><?=h($label('Vielleicht hast du genau das.'))?></h1><p><?=h($label('Die Plattform veröffentlicht keine Kontaktdaten aus Benutzerkonten. Passende neue Inserate werden dem Suchenden automatisch vorgeschlagen.'))?></p><div class="button-row"><a class="button" href="/user/wanted.php"><?=h($label('Kostenloses Gesuch erstellen'))?></a><a class="button secondary" href="/user/create-listing.php"><?=h($label('Inserat erstellen'))?></a></div></div>
<form method="get" class="panel form-grid"><label class="field"><?=h($label('Land'))?><select name="country_code"><?php foreach($countries as $code=>$name):?><option value="<?=h($code)?>" <?=$code===$country?'selected':''?>><?=h($name)?></option><?php endforeach;?></select></label><label class="field"><?=h($label('Suchbereich'))?><select name="scope"><option value="country" <?=$scope==='country'?'selected':''?>><?=h($label('Nur dieses Land'))?></option><option value="international" <?=$scope==='international'?'selected':''?>><?=h($label('International'))?></option></select></label><button class="button" type="submit"><?=h($label('Gesuche anzeigen'))?></button></form>
<?php if(!$wanted):?><section class="panel"><h2><?=h($label('Noch keine passenden Gesuche.'))?></h2><p><?=h($label('Starte dein eigenes kostenloses Gesuch.'))?></p></section><?php else:?><div class="cards"><?php foreach($wanted as $row):?><article class="panel"><p class="eyebrow"><?=h($countries[$row['country_code']]??$row['country_code'])?> · <?=h($row['category_name']??$label('Alle Kategorien'))?></p><h2><a href="?id=<?=(int)$row['id']?>&amp;scope=international"><?=h($row['title'])?></a></h2><p style="white-space:pre-wrap;overflow-wrap:anywhere"><?=h($idRaw!==null?$row['description']:mb_strimwidth($row['description'],0,240,'…','UTF-8'))?></p><p><?php if($row['min_cents']!==null):?><?=h($label('Ab'))?> <?=h(money_eur((int)$row['min_cents']))?><?php endif;?><?php if($row['max_cents']!==null):?> <?=h($label('Bis'))?> <?=h(money_eur((int)$row['max_cents']))?><?php endif;?></p><?php if($row['manufacturer']||$row['model']):?><p><?=h(trim($row['manufacturer'].' '.$row['model']))?></p><?php endif;?><?php if($row['zip']):?><p><?=h($label('Standort'))?>: <?=h($row['zip'])?><?php if($row['radius_km']!==null):?> · <?=(int)$row['radius_km']?> km <?=h($label('Luftlinie'))?><?php endif;?></p><?php endif;?><a class="button secondary" href="/user/create-listing.php"><?=h($label('Passendes Inserat erstellen'))?></a></article><?php endforeach;?></div><?php endif;?>
<?php if($idRaw===null):?><nav class="pagination" aria-label="Gesuchsseiten"><?php if($page>1):?><a href="?<?=h(http_build_query(['country_code'=>$country,'scope'=>$scope,'page'=>$page-1]))?>"><?=h($label('Zurück'))?></a><?php endif;?><span><?=h($label('Seite'))?> <?=(int)$page?></span><?php if($hasNext):?><a href="?<?=h(http_build_query(['country_code'=>$country,'scope'=>$scope,'page'=>$page+1]))?>"><?=h($label('Weiter'))?></a><?php endif;?></nav><?php endif;?></main>
<?php include __DIR__.'/../includes/footer.php';?>
